import{_ as t,a as d,o,a6 as n}from"./chunks/framework.CJDy2q7X.js";const p=JSON.parse(`{"title":"Get Customer Order","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-customer-order","title":"Get Single Customer Order","description":"Retrieve details of a specific customer order by ID.","request":"GET /api/shop/customer-orders/1\\nContent-Type: application/json\\nX-STOREFRONT-KEY: pk_storefront_PvlE42nWGsKRVIf8bDlJngTPAdWAZbIy\\nAuthorization: Bearer eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...\\n","response":"HTTP/1.1 200 OK\\n\\n{\\n  \\"id\\": 1,\\n  \\"incrementId\\": \\"1\\",\\n  \\"status\\": \\"pending\\",\\n  \\"channelName\\": \\"Default\\",\\n  \\"isGuest\\": false,\\n  \\"customerEmail\\": \\"john.doe@example.com\\",\\n  \\"customerFirstName\\": \\"John\\",\\n  \\"customerLastName\\": \\"Doe\\",\\n  \\"customerFullName\\": \\"John Doe\\",\\n  \\"shippingMethod\\": \\"flatrate_flatrate\\",\\n  \\"shippingTitle\\": \\"Flat Rate - Flat Rate\\",\\n  \\"shippingDescription\\": \\"Flat Rate Shipping\\",\\n  \\"couponCode\\": null,\\n  \\"isGift\\": false,\\n  \\"totalItemCount\\": 1,\\n  \\"totalQtyOrdered\\": 1,\\n  \\"baseCurrencyCode\\": \\"USD\\",\\n  \\"channelCurrencyCode\\": \\"USD\\",\\n  \\"orderCurrencyCode\\": \\"USD\\",\\n  \\"grandTotal\\": 65.99,\\n  \\"baseGrandTotal\\": 65.99,\\n  \\"grandTotalInvoiced\\": 0,\\n  \\"baseGrandTotalInvoiced\\": 0,\\n  \\"grandTotalRefunded\\": 0,\\n  \\"baseGrandTotalRefunded\\": 0,\\n  \\"subTotal\\": 55.99,\\n  \\"baseSubTotal\\": 55.99,\\n  \\"subTotalInvoiced\\": 0,\\n  \\"baseSubTotalInvoiced\\": 0,\\n  \\"subTotalRefunded\\": 0,\\n  \\"baseSubTotalRefunded\\": 0,\\n  \\"discountPercent\\": 0,\\n  \\"discountAmount\\": 0,\\n  \\"baseDiscountAmount\\": 0,\\n  \\"discountInvoiced\\": 0,\\n  \\"baseDiscountInvoiced\\": 0,\\n  \\"discountRefunded\\": 0,\\n  \\"baseDiscountRefunded\\": 0,\\n  \\"taxAmount\\": 0,\\n  \\"baseTaxAmount\\": 0,\\n  \\"taxAmountInvoiced\\": 0,\\n  \\"baseTaxAmountInvoiced\\": 0,\\n  \\"taxAmountRefunded\\": 0,\\n  \\"baseTaxAmountRefunded\\": 0,\\n  \\"shippingAmount\\": 10,\\n  \\"baseShippingAmount\\": 10,\\n  \\"shippingInvoiced\\": 0,\\n  \\"baseShippingInvoiced\\": 0,\\n  \\"shippingRefunded\\": 0,\\n  \\"baseShippingRefunded\\": 0,\\n  \\"shippingDiscountAmount\\": 0,\\n  \\"baseShippingDiscountAmount\\": 0,\\n  \\"shippingTaxAmount\\": 0,\\n  \\"baseShippingTaxAmount\\": 0,\\n  \\"shippingTaxRefunded\\": 0,\\n  \\"baseShippingTaxRefunded\\": 0,\\n  \\"subTotalInclTax\\": 55.99,\\n  \\"baseSubTotalInclTax\\": 55.99,\\n  \\"shippingAmountInclTax\\": 10,\\n  \\"baseShippingAmountInclTax\\": 10,\\n  \\"customerId\\": 122,\\n  \\"channelId\\": 1,\\n  \\"cartId\\": 1,\\n  \\"appliedCartRuleIds\\": \\"\\",\\n  \\"createdAt\\": \\"2026-07-21T18:01:34+05:30\\",\\n  \\"updatedAt\\": \\"2026-07-21T18:01:34+05:30\\",\\n  \\"items\\": [\\n    {\\n      \\"id\\": 279,\\n      \\"sku\\": \\"mj-coastal-hoodie\\",\\n      \\"type\\": \\"configurable\\",\\n      \\"name\\": \\"Coastal Breeze Men's Blue Zipper Hoodie\\",\\n      \\"productId\\": 59,\\n      \\"productType\\": \\"Webkul\\\\\\\\Product\\\\\\\\Models\\\\\\\\Product\\",\\n      \\"qtyOrdered\\": 1,\\n      \\"qtyShipped\\": 0,\\n      \\"qtyInvoiced\\": 0,\\n      \\"qtyCanceled\\": 0,\\n      \\"qtyRefunded\\": 0,\\n      \\"price\\": 55.99,\\n      \\"basePrice\\": 55.99,\\n      \\"total\\": 55.99,\\n      \\"baseTotal\\": 55.99,\\n      \\"discountPercent\\": 0,\\n      \\"discountAmount\\": 0,\\n      \\"taxPercent\\": 0,\\n      \\"taxAmount\\": 0,\\n      \\"priceInclTax\\": 55.99,\\n      \\"totalInclTax\\": 55.99\\n    }\\n  ],\\n  \\"addresses\\": [\\n    {\\n      \\"id\\": 220,\\n      \\"addressType\\": \\"order_shipping\\",\\n      \\"firstName\\": \\"John\\",\\n      \\"lastName\\": \\"Doe\\",\\n      \\"gender\\": null,\\n      \\"companyName\\": \\"\\",\\n      \\"address\\": \\"123 Main St\\",\\n      \\"city\\": \\"Los Angeles\\",\\n      \\"state\\": \\"CA\\",\\n      \\"country\\": \\"US\\",\\n      \\"postcode\\": \\"90001\\",\\n      \\"email\\": \\"john.doe@example.com\\",\\n      \\"phone\\": \\"2125551234\\",\\n      \\"vatId\\": null\\n    },\\n    {\\n      \\"id\\": 221,\\n      \\"addressType\\": \\"order_billing\\",\\n      \\"firstName\\": \\"John\\",\\n      \\"lastName\\": \\"Doe\\",\\n      \\"gender\\": null,\\n      \\"companyName\\": \\"\\",\\n      \\"address\\": \\"123 Main St\\",\\n      \\"city\\": \\"Los Angeles\\",\\n      \\"state\\": \\"CA\\",\\n      \\"country\\": \\"US\\",\\n      \\"postcode\\": \\"90001\\",\\n      \\"email\\": \\"john.doe@example.com\\",\\n      \\"phone\\": \\"2125551234\\",\\n      \\"vatId\\": null\\n    }\\n  ],\\n  \\"payment\\": {\\n    \\"id\\": 20,\\n    \\"method\\": \\"moneytransfer\\",\\n    \\"methodTitle\\": \\"Money Transfer\\"\\n  },\\n  \\"shipments\\": []\\n}\\n","commonErrors":[{"error":"404 Not Found","cause":"No such order, or the order belongs to another customer — the two are indistinguishable","solution":"Verify the order ID and ensure it belongs to the authenticated customer"},{"error":"401 Unauthorized","cause":"Missing or invalid Bearer token","solution":"Login and provide a valid customer authentication token"},{"error":"403 Forbidden","cause":"Storefront key is missing or invalid","solution":"Provide a valid X-STOREFRONT-KEY header"}]}]},"headers":[],"relativePath":"api/rest-api/shop/customer-orders/get-customer-order.md","filePath":"api/rest-api/shop/customer-orders/get-customer-order.md","lastUpdated":1786429091000}`),a={name:"api/rest-api/shop/customer-orders/get-customer-order.md"};function r(s,e,c,i,l,h){return o(),d("div",null,e[0]||(e[0]=[n('<h1 id="get-customer-order" tabindex="-1">Get Customer Order <a class="header-anchor" href="#get-customer-order" aria-label="Permalink to &quot;Get Customer Order&quot;">​</a></h1><p>Retrieve detailed information for a specific customer order by its ID. Customers can only access their own orders — requesting another customer&#39;s order returns a 404, preventing enumeration attacks.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/customer-orders/{id}</span></span></code></pre></div><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Content-Type</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>Bearer token (customer login required)</td></tr></tbody></table><h2 id="path-parameters" tabindex="-1">Path Parameters <a class="header-anchor" href="#path-parameters" aria-label="Permalink to &quot;Path Parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Yes</td><td>Customer order ID</td></tr></tbody></table><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>One order, flat, with four nested blocks at the end. There is no wrapper object.</p><h3 id="identity-and-status" tabindex="-1">Identity and status <a class="header-anchor" href="#identity-and-status" aria-label="Permalink to &quot;Identity and status&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Internal order ID — the value used in this path.</td></tr><tr><td><code>incrementId</code></td><td>string</td><td>Order number shown to the customer.</td></tr><tr><td><code>status</code></td><td>string</td><td>Order status — see <a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get Customer Orders</a> for the list.</td></tr><tr><td><code>channelName</code></td><td>string</td><td>Channel the order was placed on.</td></tr><tr><td><code>isGuest</code></td><td>integer</td><td><code>1</code> when the order was placed without an account.</td></tr><tr><td><code>isGift</code></td><td>integer</td><td><code>1</code> when the order was marked as a gift.</td></tr><tr><td><code>customerId</code> / <code>channelId</code> / <code>cartId</code></td><td>integer</td><td>Related record IDs.</td></tr><tr><td><code>customerEmail</code> / <code>customerFirstName</code> / <code>customerLastName</code> / <code>customerFullName</code></td><td>string</td><td>Contact details captured at checkout.</td></tr><tr><td><code>createdAt</code> / <code>updatedAt</code></td><td>string</td><td>ISO 8601 timestamps.</td></tr></tbody></table><h3 id="shipping-and-discounts" tabindex="-1">Shipping and discounts <a class="header-anchor" href="#shipping-and-discounts" aria-label="Permalink to &quot;Shipping and discounts&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>shippingMethod</code></td><td>string</td><td>Method code, e.g. <code>flatrate_flatrate</code>.</td></tr><tr><td><code>shippingTitle</code> / <code>shippingDescription</code></td><td>string</td><td>Human-readable method label and description.</td></tr><tr><td><code>couponCode</code></td><td>string</td><td>Coupon applied at checkout, <code>null</code> when none was used.</td></tr><tr><td><code>appliedCartRuleIds</code></td><td>string</td><td>Comma-separated IDs of the cart rules that fired.</td></tr><tr><td><code>totalItemCount</code> / <code>totalQtyOrdered</code></td><td>integer</td><td>Distinct lines, and the sum of their quantities.</td></tr></tbody></table><h3 id="money" tabindex="-1">Money <a class="header-anchor" href="#money" aria-label="Permalink to &quot;Money&quot;">​</a></h3><p>Every monetary figure comes in an order-currency form and a <code>base*</code> form in the store&#39;s base currency. Each family also carries <code>Invoiced</code> and <code>Refunded</code> variants, so a client can show what has actually been billed and returned rather than only what was ordered.</p><table tabindex="0"><thead><tr><th>Family</th><th>Fields</th></tr></thead><tbody><tr><td>Grand total</td><td><code>grandTotal</code>, <code>baseGrandTotal</code>, <code>grandTotalInvoiced</code>, <code>baseGrandTotalInvoiced</code>, <code>grandTotalRefunded</code>, <code>baseGrandTotalRefunded</code></td></tr><tr><td>Subtotal</td><td><code>subTotal</code>, <code>baseSubTotal</code>, <code>subTotalInvoiced</code>, <code>baseSubTotalInvoiced</code>, <code>subTotalRefunded</code>, <code>baseSubTotalRefunded</code>, <code>subTotalInclTax</code>, <code>baseSubTotalInclTax</code></td></tr><tr><td>Discount</td><td><code>discountPercent</code>, <code>discountAmount</code>, <code>baseDiscountAmount</code>, <code>discountInvoiced</code>, <code>baseDiscountInvoiced</code>, <code>discountRefunded</code>, <code>baseDiscountRefunded</code></td></tr><tr><td>Tax</td><td><code>taxAmount</code>, <code>baseTaxAmount</code>, <code>taxAmountInvoiced</code>, <code>baseTaxAmountInvoiced</code>, <code>taxAmountRefunded</code>, <code>baseTaxAmountRefunded</code></td></tr><tr><td>Shipping</td><td><code>shippingAmount</code>, <code>baseShippingAmount</code>, <code>shippingInvoiced</code>, <code>baseShippingInvoiced</code>, <code>shippingRefunded</code>, <code>baseShippingRefunded</code>, <code>shippingDiscountAmount</code>, <code>baseShippingDiscountAmount</code>, <code>shippingTaxAmount</code>, <code>baseShippingTaxAmount</code>, <code>shippingTaxRefunded</code>, <code>baseShippingTaxRefunded</code>, <code>shippingAmountInclTax</code>, <code>baseShippingAmountInclTax</code></td></tr><tr><td>Currency</td><td><code>orderCurrencyCode</code>, <code>baseCurrencyCode</code>, <code>channelCurrencyCode</code></td></tr></tbody></table><p>Amounts are raw numbers, not formatted strings — apply the symbol for <code>orderCurrencyCode</code> client-side.</p><h3 id="items" tabindex="-1">Items <a class="header-anchor" href="#items" aria-label="Permalink to &quot;Items&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Order-line ID.</td></tr><tr><td><code>sku</code> / <code>name</code></td><td>string</td><td>Product identity as captured at checkout.</td></tr><tr><td><code>type</code> / <code>productType</code></td><td>string</td><td>Product type, e.g. <code>simple</code>.</td></tr><tr><td><code>productId</code></td><td>integer</td><td>The catalog product; use it to link back to the product page.</td></tr><tr><td><code>qtyOrdered</code> / <code>qtyShipped</code> / <code>qtyInvoiced</code> / <code>qtyCanceled</code> / <code>qtyRefunded</code></td><td>integer</td><td>Per-line quantity breakdown.</td></tr><tr><td><code>price</code> / <code>basePrice</code> / <code>priceInclTax</code></td><td>float</td><td>Unit price.</td></tr><tr><td><code>total</code> / <code>baseTotal</code> / <code>totalInclTax</code></td><td>float</td><td>Line total.</td></tr><tr><td><code>discountPercent</code> / <code>discountAmount</code> / <code>taxPercent</code> / <code>taxAmount</code></td><td>float</td><td>Per-line discount and tax.</td></tr></tbody></table><h3 id="addresses" tabindex="-1">Addresses <a class="header-anchor" href="#addresses" aria-label="Permalink to &quot;Addresses&quot;">​</a></h3><p>The <code>addresses</code> array holds the billing and shipping addresses, told apart by <code>addressType</code>.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>integer</td><td>Address record ID.</td></tr><tr><td><code>addressType</code></td><td>string</td><td><code>order_billing</code> or <code>order_shipping</code>.</td></tr><tr><td><code>firstName</code> / <code>lastName</code> / <code>gender</code> / <code>companyName</code> / <code>vatId</code></td><td>string</td><td>Recipient details.</td></tr><tr><td><code>address</code> / <code>city</code> / <code>state</code> / <code>country</code> / <code>postcode</code></td><td>string</td><td>Location, with the street under <code>address</code>.</td></tr><tr><td><code>email</code> / <code>phone</code></td><td>string</td><td>Contact details captured with the address.</td></tr></tbody></table><h3 id="payment-and-shipments" tabindex="-1">Payment and Shipments <a class="header-anchor" href="#payment-and-shipments" aria-label="Permalink to &quot;Payment and Shipments&quot;">​</a></h3><p>The <code>payment</code> block is a single object of <code>id</code>, <code>method</code>, and <code>methodTitle</code>. <code>shipments</code> is an array, empty until the order ships.</p><h2 id="error-responses" tabindex="-1">Error Responses <a class="header-anchor" href="#error-responses" aria-label="Permalink to &quot;Error Responses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Status</th><th>Body <code>detail</code></th><th>Cause</th></tr></thead><tbody><tr><td><code>404</code></td><td><code>Customer order with ID &quot;999999&quot; not found</code></td><td>No such order, <strong>or</strong> the order belongs to another customer. The two cases are deliberately indistinguishable.</td></tr><tr><td><code>403</code></td><td><code>Unauthenticated. Please login to perform this action</code></td><td>No customer Bearer token was sent.</td></tr><tr><td><code>401</code></td><td>—</td><td>The storefront key header was missing or wrong.</td></tr></tbody></table><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Order detail page</strong> — one call returns the lines, both addresses, and the payment method, so no follow-up fetches are needed.</li><li><strong>&quot;Partially shipped&quot; badge</strong> — compare <code>qtyShipped</code> against <code>qtyOrdered</code> per line; the order-level <code>status</code> alone does not show partial fulfilment.</li><li><strong>Refund summary</strong> — the <code>*Refunded</code> figures state what was actually returned, which the order total does not reflect.</li><li><strong>Reorder</strong> — <code>items[].productId</code> and <code>qtyOrdered</code> are enough to rebuild a cart.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Show <code>incrementId</code>, keep <code>id</code></strong> — the increment ID is the number on the customer&#39;s confirmation email; the plain <code>id</code> is internal and addresses this endpoint.</li><li><strong>Read the <code>Invoiced</code> and <code>Refunded</code> variants before showing &quot;amount paid&quot;</strong> — <code>grandTotal</code> is what was ordered, not what has been billed.</li><li><strong>Do not treat an empty <code>shipments</code> array as an error</strong> — it simply means nothing has shipped yet.</li><li><strong>Split <code>addresses</code> by <code>addressType</code></strong> — both live in one array, and a page that renders <code>addresses[0]</code> as billing will be wrong whenever the order shipped first.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/customer-orders/get-customer-orders.html">Get All Customer Orders</a> — the customer&#39;s order history</li><li><a href="/api/rest-api/shop/checkout/place-order.html">Place Order</a> — turn the prepared cart into an order</li><li><a href="/api/rest-api/shop/customers/get-customer-profile.html">Get Customer Profile</a> — read the authenticated customer&#39;s account details</li></ul>',33)]))}const m=t(a,[["render",r]]);export{p as __pageData,m as default};
